import sys
import requests
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_config(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    service = root.find('service')
    return service.attrib['url'], service.attrib['token']

def fetch_flags(url, token):
    headers = {'Authorization': f'Bearer {token}'}
    response = requests.get(url, params={'format': 'xml'}, headers=headers)
    response.raise_for_status()
    return ET.fromstring(response.content)

def update_flags(existing_flags, new_flags):
    existing_names = {flag.attrib['name'] for flag in existing_flags}
    new_names = {flag.attrib['name'] for flag in new_flags}

    updated = 0
    added = 0

    # Process existing flags
    for flag in existing_flags:
        if flag.attrib['name'] in new_names:
            if flag.attrib['enabled'] != new_flags[new_names.index(flag.attrib['name'])].attrib['enabled']:
                updated += 1
        else:
            pass  # Keep existing flags not in new_flags

    # Process new flags
    for flag in new_flags:
        if flag.attrib['name'] not in existing_names:
            added += 1

    return existing_flags, new_names, updated, added

def write_flags(flags, output_path):
    tree = ET.Element('flags')
    for flag in flags:
        child = ET.SubElement(tree, 'flag')
        child.attrib['name'] = flag.attrib['name']
        child.attrib['enabled'] = flag.attrib['enabled']
    ET.dump(tree, sys.stdout, encoding='utf-8', xml_declaration=True)

def main():
    if len(sys.argv) != 2:
        print("Usage: python flag_sync.py config.xml", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    url, token = parse_config(config_path)

    try:
        new_flags = fetch_flags(url, token)
    except requests.RequestException as e:
        print(f"Error fetching flags: {e}", file=sys.stderr)
        sys.exit(1)

    existing_flags = []
    try:
        tree = ET.parse('flags.xml')
        existing_flags = tree.findall('.//flag')
    except FileNotFoundError:
        pass

    existing_names = {flag.attrib['name'] for flag in existing_flags}
    new_names = {flag.attrib['name'] for flag in new_flags}

    updated = 0
    added = 0

    # Process existing flags to update enabled status
    for flag in existing_flags:
        if flag.attrib['name'] in new_names:
            new_flag = next(f for f in new_flags if f.attrib['name'] == flag.attrib['name'])
            if flag.attrib['enabled'] != new_flag.attrib['enabled']:
                flag.attrib['enabled'] = new_flag.attrib['enabled']
                updated += 1

    # Collect all flags: existing + new (not already present)
    all_flags = []
    for flag in existing_flags:
        if flag.attrib['name'] not in new_names:
            all_flags.append(flag)
    for flag in new_flags:
        if flag.attrib['name'] not in existing_names:
            all_flags.append(flag)

    # Add new flags to existing flags
    for flag in new_flags:
        if flag.attrib['name'] not in existing_names:
            existing_flags.append(flag)
            added += 1

    # Write the updated flags
    tree = ET.ElementTree(existing_flags)
    tree.write('flags.xml', encoding='utf-8', xml_declaration=True)

    print(f"added={added} updated={updated}")

if __name__ == "__main__":
    main()
